const raw = $input.first().json.output;
let parsed;
try {
  const cleaned = typeof raw === 'string' ? raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim() : raw;
  parsed = typeof cleaned === 'string' ? JSON.parse(cleaned) : cleaned;
} catch (e) {
  parsed = { mensaje: String(raw), botones: [] };
}

const mensaje = parsed.mensaje || String(raw);
const botonesRaw = Array.isArray(parsed.botones) ? parsed.botones : [];

const inline_keyboard = botonesRaw.map(fila =>
  (Array.isArray(fila) ? fila : [fila]).map(b => ({
    text: b.texto || b.text || 'Opcion',
    callback_data: String(b.callback_data || b.texto || b.text || 'NA').slice(0, 64)
  }))
).filter(fila => fila.length > 0);

return [{
  json: {
    mensaje,
    tiene_botones: inline_keyboard.length > 0,
    reply_markup: inline_keyboard.length > 0 ? { inline_keyboard } : undefined
  }
}];
